SELECT COUNT(1)
FROM eat_list
WHERE user_id = #{userId}

    AND status = #{status}

SELECT id, user_id AS userId, dish_id AS dishId, status, source_lottery_record_id AS sourceLotteryRecordId, note, created_at AS createdAt, eaten_at AS eatenAt, updated_at AS updatedAt FROM eat_list WHERE user_id = #{userId}
AND status = #{status}
ORDER BY updated_at DESC, id DESC LIMIT #{offset}, #{size}

SELECT d.id AS dishId, d.name AS dishName, d.price, d.average_score AS score, m.name AS merchantName, c.name AS canteenName, di.image_url AS imageUrl FROM dish d INNER JOIN merchant m ON m.id = d.merchant_id INNER JOIN canteen c ON c.id = d.canteen_id LEFT JOIN dish_image di ON di.dish_id = d.id WHERE d.id IN
#{dishId}
ORDER BY d.id ASC, di.is_cover DESC, di.sort_order ASC, di.id ASC
